namespace ghidra.app.util.exporter;




using ghidra.app.util;
using ghidra.app.util;
using ghidra.framework.model;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.program.model.mem;
using ghidra.util;
using ghidra.util.task;

/**
 * An {@link Exporter} that can export memory blocks as raw bytes
 */
public class BinaryExporter : ProgramExporter {

	public BinaryExporter() : base("Raw Bytes", "bin", new HelpLocation("ExporterPlugin", "binary"))
    {
	}

	/* @Override */
	public bool export(File file, DomainObject domainObj, AddressSetView addrSet,
			TaskMonitor monitor)
    {

		Program program;
		try {
			program = getProgram(domainObj);
		}
		catch (ClassCastException e) {
			log.appendMsg("Unsupported type: " + domainObj.GetType().getName());
			return false;
		}

		Memory memory = program.getMemory();
		AddressSetView initializedAddressSet = memory.getAllInitializedAddressSet();

		if (addrSet == null) {
			addrSet = initializedAddressSet;
		}
		else {
			addrSet = addrSet.intersect(initializedAddressSet);
		}

		try
{
    using (FileOutputStream fos = new FileOutputStream(file))
    {

			AddressRangeIterator iter = addrSet.getAddressRanges();
			while (iter.hasNext()) {
				AddressRange range = iter.next();
				byte[] mem = new byte[(int) range.getLength()];
				int numBytes = memory.getBytes(range.getMinAddress(), mem);
				fos.write(mem, 0, numBytes);
			}
		
    }
}
		catch (MemoryAccessException e) {
			throw new ExporterException(e);
		}

		return true;
	}

	/* @Override */
	public List<Option> getOptions(DomainObjectService domainObjectService) {
		return EMPTY_OPTIONS;
	}

	/* @Override */
	public void setOptions(List<Option> options) {
		// No options
	}
}
